"""Baseline: measured outline extruded, holes cut. Generated by baseline_cad.py."""
import cadquery as cq


def build_part(
    thickness=3.0,
    corner1_u=34.15, corner1_v=-20.36,
    corner2_u=19.79, corner2_v=-19.79,
    corner3_u=6.03, corner3_v=-20.18,
    corner4_u=-39.6, corner4_v=-20.07,
    corner5_u=-39.74, corner5_v=20.25,
    corner6_u=31.74, corner6_v=20.28,
    corner7_u=39.5, corner7_v=12.28,
    corner8_u=38.53, corner8_v=-19.48,
    hole1_u=-31.82, hole1_v=12.23, hole1_diameter=6.08,
    hole2_u=-31.81, hole2_v=-12.07, hole2_diameter=6.02,
    hole3_u=31.34, hole3_v=-12.05, hole3_diameter=5.99,
    hole4_u=31.67, hole4_v=12.2, hole4_diameter=6.05,
):
    part = cq.Workplane("XY").polyline([(corner1_u, corner1_v), (corner2_u, corner2_v), (corner3_u, corner3_v), (corner4_u, corner4_v), (corner5_u, corner5_v), (corner6_u, corner6_v), (corner7_u, corner7_v), (corner8_u, corner8_v)]).close().extrude(thickness)
    part = part.cut(cq.Workplane("XY", origin=(hole1_u, hole1_v, -1)).circle(hole1_diameter / 2).extrude(thickness + 2))
    part = part.cut(cq.Workplane("XY", origin=(hole2_u, hole2_v, -1)).circle(hole2_diameter / 2).extrude(thickness + 2))
    part = part.cut(cq.Workplane("XY", origin=(hole3_u, hole3_v, -1)).circle(hole3_diameter / 2).extrude(thickness + 2))
    part = part.cut(cq.Workplane("XY", origin=(hole4_u, hole4_v, -1)).circle(hole4_diameter / 2).extrude(thickness + 2))
    return part
